import torch
import torch.nn as nn

# Define the Encoder class
class Encoder(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_layers):
        super(Encoder, self).__init__()
        self.encoder_layers = nn.ModuleList([nn.TransformerEncoderLayer(d_model=hidden_dim, nhead=8, dim_feedforward=hidden_dim, dropout=0.1) for _ in range(num_layers)])

    def forward(self, x):
        for layer in self.encoder_layers:
            x = layer(x)
        return x

# Define the Decoder class
class Decoder(nn.Module):
    def __init__(self, input_dim, hidden_dim, num_layers):
        super(Decoder, self).__init__()
        self.decoder_layers = nn.ModuleList([nn.TransformerDecoderLayer(d_model=hidden_dim, nhead=8, dim_feedforward=hidden_dim, dropout=0.1) for _ in range(num_layers)])

    def forward(self, x):
        for layer in self.decoder_layers:
            x = layer(x)
        return x

